<script setup lang="ts">
import {dismissAfterFourSeconds} from '../temporary-message'
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { teacherBusyReason } from '../room-availability'
import { scheduleApi, days } from '../schedules'
const emit=defineEmits<{saving:[value:boolean]}>()
const school=ref<any>(null), data=ref<any>(null), loading=ref(false), busy=ref(false), error=ref(''), message=ref('')
dismissAfterFourSeconds(message)
const yearId=ref(0),grade=ref(''),search=ref(''),selectedClass=ref(0),selectedRoom=ref<any>(null),mode=ref('allocate'),dialog=ref<HTMLDialogElement|null>(null)
const root=ref<HTMLElement|null>(null),dragging=ref(false),pointerX=ref(0),pointerY=ref(0)
let cleanup:(()=>void)|undefined,suppress=false
const floors=[5,4,3,2,1]
const classes=computed(()=>school.value?.classes.filter((c:any)=>c.year_id===yearId.value && c.is_active)??[])
const grades=computed<string[]>(()=>[...new Set<string>(classes.value.map((c:any)=>c.grade_label))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})))
const visibleClasses=computed(()=>classes.value.filter((c:any)=>(!grade.value||c.grade_label===grade.value) && (c.grade_label+' '+c.name).toLowerCase().includes(search.value.toLowerCase())))
const className=(c:any)=>c?`Grade ${c.grade_label} · Class ${c.name}`:'Choose a class'
const chosenClass=computed(()=>classes.value.find((c:any)=>c.id===selectedClass.value))
const assignment=(roomId:number)=>data.value?.assignments.find((a:any)=>a.year_id===yearId.value && a.room_id===roomId)
const currentRoom=computed(()=>data.value?.assignments.find((a:any)=>a.class_id===selectedClass.value)?.room_id)
const classById=(id:number)=>school.value?.classes.find((c:any)=>c.id===id)
const roomBookings=(id:number)=>data.value?.bookings.filter((b:any)=>b.room_id===id && !b.is_cancelled && classById(b.class_id)?.year_id===yearId.value)??[]
const subjects=computed(()=>school.value?.subjects.filter((s:any)=>school.value.links.some((l:any)=>l.class_id===selectedClass.value && l.offering_id===s.id))??[])
const teachers=computed(()=>school.value?.teachers.filter((t:any)=>t.is_active)??[])
const form=reactive({offering_id:0,teacher_id:0,day_of_week:7,start_time:'10:00',end_time:'11:00',starts_on:'',ends_on:'',repeats_weekly:false,name:''})
async function load(){loading.value=true;error.value='';try{const [s,r]=await Promise.all([scheduleApi('admin/school'),scheduleApi('admin/school/rooms')]);school.value=s;data.value=r;if(!s.years.some((y:any)=>y.id===yearId.value))yearId.value=s.years.find((y:any)=>y.start_date<=s.today && y.end_date>=s.today)?.id??s.years[0]?.id??0;if(!classes.value.some((c:any)=>c.id===selectedClass.value))selectedClass.value=0}catch(e){error.value=e instanceof Error?e.message:'Unable to load rooms.'}finally{loading.value=false}}
async function mutate(path:string,method:string,value:object){if(busy.value||!school.value)return;busy.value=true;emit('saving',true);error.value='';message.value='';try{const result=await scheduleApi('admin/school/'+path,method,{...value,revision:school.value.revision});await load();if(error.value)return false;message.value=result.message;return true}catch(e){error.value=e instanceof Error?e.message:'Unable to save.';return false}finally{busy.value=false;emit('saving',false)}}
function selectClass(id:number){if(!busy.value && !suppress){selectedClass.value=id;message.value='Selected '+className(classes.value.find((c:any)=>c.id===id))+'. Choose a room, or drag the class card.'}}
const availableOnly=ref(true)
const canCheckTeachers=computed(()=>Boolean(form.starts_on && form.start_time && form.end_time && form.start_time<form.end_time))
const teacherStatus=(id:number)=>school.value?teacherBusyReason(id,selectedClass.value,form.starts_on,form.start_time,form.end_time,school.value,data.value?.bookings??[]):'Loading availability'
const availableTeachers=computed(()=>teachers.value.filter((t:any)=>canCheckTeachers.value && !teacherStatus(t.id)))
const displayedTeachers=computed(()=>availableOnly.value && canCheckTeachers.value?availableTeachers.value:teachers.value)
const selectedTeacherBusy=computed(()=>form.teacher_id && canCheckTeachers.value?teacherStatus(form.teacher_id):'')
const selectedLesson=ref(0)
const bookingLessons=computed(()=>{
 const subject=subjects.value.find((s:any)=>s.id===form.offering_id)
 const term=school.value?.terms.find((t:any)=>t.id===subject?.semester_id)
 if(!term || !form.starts_on || form.starts_on<term.start_date || form.starts_on>term.end_date)return []
 const day=new Date(form.starts_on+'T00:00:00Z').getUTCDay()||7
 return (school.value?.meetings??[]).filter((m:any)=>m.course_offering_id===form.offering_id && m.day_of_week===day).sort((a:any,b:any)=>a.start_time.localeCompare(b.start_time))
})
function applyLesson(){
 const lesson=bookingLessons.value.find((m:any)=>m.id===selectedLesson.value)
 form.start_time=lesson?.start_time.slice(0,5)??''
 form.end_time=lesson?.end_time.slice(0,5)??''
}
function syncBooking(){
 error.value=''
 form.teacher_id=school.value?.subject_teachers.find((t:any)=>t.offering_id===form.offering_id)?.teacher_id??0
 form.ends_on=form.starts_on
 selectedLesson.value=bookingLessons.value[0]?.id??0
 applyLesson()
}
function chooseSubject(){syncBooking()}
async function openRoom(room:any,action='allocate'){if(busy.value||loading.value||suppress)return;selectedRoom.value=room;mode.value=action;error.value='';Object.assign(form,{offering_id:subjects.value[0]?.id??0,teacher_id:0,day_of_week:7,start_time:'10:00',end_time:'11:00',repeats_weekly:false,starts_on:school.value.today,ends_on:school.value.today,name:room.name});chooseSubject();await nextTick();dialog.value?.showModal()}
function close(){if(!busy.value){dialog.value?.close();selectedRoom.value=null}}
async function submit(){if(!selectedRoom.value)return;let ok=false
 if(mode.value==='rename')ok=!!await mutate('rooms/'+selectedRoom.value.id,'PUT',{name:form.name})
 else if(selectedRoom.value.kind==='regular')ok=!!await mutate('room-assignments','POST',{class_id:selectedClass.value,room_id:selectedRoom.value.id})
 else {if(form.end_time<=form.start_time){error.value='End time must be after start time on the same day.';return}const date=new Date(form.starts_on+'T00:00:00Z');ok=!!await mutate('room-bookings','POST',{...form,room_id:selectedRoom.value.id,class_id:selectedClass.value,repeats_weekly:false,ends_on:form.starts_on,day_of_week:date.getUTCDay()||7})}
 if(ok)close()
}
async function release(classId:number){if(window.confirm('Remove this class’s usual classroom assignment?'))await mutate('room-assignments/'+classId,'DELETE',{})}
async function cancelBooking(id:number){if(window.confirm('Cancel this room booking? Its record will remain saved.'))await mutate('room-bookings/'+id+'/cancel','PUT',{})}
function startDrag(event:PointerEvent,id:number){if(busy.value||event.button!==0)return;cleanup?.();const x=event.clientX,y=event.clientY,source=event.currentTarget as HTMLElement;source.setPointerCapture(event.pointerId)
 const move=(e:PointerEvent)=>{if(!dragging.value && Math.hypot(e.clientX-x,e.clientY-y)>6){selectedClass.value=id;dragging.value=true}pointerX.value=e.clientX;pointerY.value=e.clientY;if(dragging.value)e.preventDefault()}
 const stop=(e:PointerEvent)=>{const active=dragging.value,target=document.elementFromPoint(e.clientX,e.clientY)?.closest<HTMLElement>('[data-room-id]');cleanup?.();if(!active)return;suppress=true;setTimeout(()=>{suppress=false},0);if(target && root.value?.contains(target)){const room=data.value.rooms.find((r:any)=>r.id===Number(target.dataset.roomId));if(room){suppress=false;void openRoom(room)}}}
 cleanup=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);window.removeEventListener('pointercancel',abort);if(source.hasPointerCapture(event.pointerId))source.releasePointerCapture(event.pointerId);dragging.value=false;cleanup=undefined}
 const abort=()=>cleanup?.();window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',stop);window.addEventListener('pointercancel',abort)
}
onBeforeUnmount(()=>cleanup?.());onMounted(load)
</script>
<template>
<section ref="root" class="room-board" :aria-busy="busy||loading">
<div v-if="dragging" class="drag-ghost" :style="{left:pointerX+14+'px',top:pointerY+14+'px'}">{{className(chosenClass)}}</div>
<div class="board-heading"><div><p class="eyebrow">BUILDING & SHARED SPACES</p><h2>Every class has a place.</h2><p class="muted">30 usual classrooms · 10 special rooms · Nepal time</p></div><button class="secondary" :disabled="busy||loading" @click="load">Refresh rooms</button></div>
<p v-if="error && !selectedRoom" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><p v-if="loading" role="status">Loading room board…</p>
<template v-if="school && data"><p v-if="!school.profile">Set up the school profile in School classes first.</p><template v-else>
<div class="board-toolbar"><label>Academic year<select v-model="yearId" :disabled="busy" @change="selectedClass=0;grade=''"> <option :value="0">Choose a year</option><option v-for="y in school.years" :key="y.id" :value="y.id">{{y.name}}</option></select></label><p><span class="key regular"></span> Usual classroom <span class="key special"></span> Special room · ends in 07 / 08</p></div>
<div class="board-workspace"><aside class="class-library"><h3>Classes <span>{{visibleClasses.length}}</span></h3><label>Grade<select v-model="grade" :disabled="busy"><option value="">All grades</option><option v-for="g in grades" :key="g" :value="g">Grade {{g}}</option></select></label><label>Find a class<input v-model="search" type="search" placeholder="Grade or section"></label><p class="muted">Drag a class onto a room, or select it and click the room.</p><div class="class-list"><button v-for="c in visibleClasses" :key="c.id" type="button" class="class-card" :class="{selected:selectedClass===c.id}" :aria-pressed="selectedClass===c.id" :disabled="busy" draggable="false" @pointerdown="startDrag($event,c.id)" @click="selectClass(c.id)"><strong>{{className(c)}}</strong><small>{{data.assignments.find((a:any)=>a.class_id===c.id)?'Usual room '+data.assignments.find((a:any)=>a.class_id===c.id).room_id:'Usual classroom not assigned'}}</small></button><p v-if="!visibleClasses.length">No matching classes. Create classes in School classes first.</p></div></aside>
<div class="building-area"><p class="board-instruction">{{chosenClass?className(chosenClass)+' selected — choose a destination.':'Select a class to allocate it, or click a room to see its bookings.'}}</p><div class="building-scroll" tabindex="0" aria-label="Five-floor building, scroll horizontally on small screens"><div class="building"><div v-for="floor in floors" :key="floor" class="floor"><div class="floor-label"><strong>{{floor}}</strong><small>FLOOR</small></div><article v-for="r in data.rooms.filter((r:any)=>r.floor_number===floor)" :key="r.id" class="room" :class="[r.kind,{occupied:assignment(r.id)}]" :data-room-id="r.id"><button type="button" class="room-target" :disabled="busy||!yearId" :aria-label="'Room '+r.id+' '+r.name" @click="openRoom(r)"><strong class="room-number">{{r.id}}</strong><span class="room-name">{{r.name}}</span><span v-if="r.kind==='regular'" class="room-status">{{assignment(r.id)?className(classById(assignment(r.id).class_id)):'Available for class'}}</span><span v-else class="room-status">{{roomBookings(r.id).length}} booking(s)</span></button><button type="button" class="rename" :disabled="busy" :aria-label="'Rename room '+r.id" @click="openRoom(r,'rename')">Edit name</button></article></div></div></div><p class="muted">Usual classrooms are assigned for the academic year. Special rooms are reserved for a start and end time on one date. Room bookings reserve space separately from subject timetable lessons.</p></div></div>
</template></template>
<dialog ref="dialog" aria-labelledby="room-dialog-title" @cancel.prevent="close"><template v-if="selectedRoom"><div class="dialog-heading"><div><p class="eyebrow">{{selectedRoom.kind==='special'?'SPECIAL ROOM':'USUAL CLASSROOM'}}</p><h3 id="room-dialog-title">{{selectedRoom.id}} · {{selectedRoom.name}}</h3></div><button type="button" class="secondary" :disabled="busy" aria-label="Close room form" @click="close">Close</button></div><p v-if="error" class="error" role="alert">{{error}}</p>
<form v-if="mode==='rename'" @submit.prevent="submit"><label>Room name / purpose<input v-model="form.name" required maxlength="100" :disabled="busy"></label><p class="muted">Room number, floor and regular/special type stay fixed.</p><button :disabled="busy">Save room name</button></form>
<template v-else><p v-if="!chosenClass" class="muted">Select a class from the sidebar before assigning or booking this room.</p><form v-else @submit.prevent="submit"><fieldset :disabled="busy"><p class="chosen">{{className(chosenClass)}}</p><template v-if="selectedRoom.kind==='regular'"><p>Assign this as the class’s usual classroom for the selected academic year.</p><p v-if="currentRoom && currentRoom!==selectedRoom.id">This will move the class from room {{currentRoom}}.</p><p v-if="assignment(selectedRoom.id) && assignment(selectedRoom.id).class_id!==selectedClass" class="error">This room already belongs to {{className(classById(assignment(selectedRoom.id).class_id))}}. Release that assignment before moving another class here.</p><button :disabled="assignment(selectedRoom.id) && assignment(selectedRoom.id).class_id!==selectedClass">{{currentRoom && currentRoom!==selectedRoom.id?'Move class here':'Assign usual classroom'}}</button></template>
<template v-else><div class="form-grid"><label>Class subject<select v-model="form.offering_id" required @change="chooseSubject"><option :value="0" disabled>Choose a linked subject</option><option v-for="s in subjects" :key="s.id" :value="s.id">{{s.course_name}} · {{school.terms.find((t:any)=>t.id===s.semester_id)?.name}}</option></select></label><div class="teacher-picker"><label>Supervising teacher<select v-model="form.teacher_id" required><option v-if="selectedTeacherBusy && availableOnly" :value="form.teacher_id" disabled>Selected teacher is busy - choose another</option><option :value="0" disabled>Choose a teacher</option><option v-for="t in displayedTeachers" :key="t.id" :value="t.id" :disabled="canCheckTeachers && !!teacherStatus(t.id)">{{t.name}} · {{canCheckTeachers?(teacherStatus(t.id) || 'Available'):'Choose time first'}}</option></select></label><label class="check"><input v-model="availableOnly" type="checkbox">Available only <span v-if="canCheckTeachers">({{availableTeachers.length}})</span></label><small v-if="!canCheckTeachers">Choose date and times to check availability.</small><small v-else-if="selectedTeacherBusy" role="status">Assigned teacher: {{selectedTeacherBusy}}. Select an available replacement.</small><small v-else-if="!availableTeachers.length" role="status">No available teachers. Try another time.</small></div></div><p v-if="!subjects.length" class="muted">Link subjects and teachers to this class in School classes first.</p><label v-if="bookingLessons.length>1">Scheduled lesson<select v-model="selectedLesson" @change="applyLesson"><option v-for="lesson in bookingLessons" :key="lesson.id" :value="lesson.id">{{lesson.start_time.slice(0,5)}} - {{lesson.end_time.slice(0,5)}}</option></select></label><p class="muted" role="status">{{bookingLessons.length?'Time and supervising teacher filled from this subject’s timetable.':'No lesson for this subject on the selected date. Choose another date, or enter a one-off time.'}}</p><div class="form-grid"><label>Booking date<input v-model="form.starts_on" type="date" required @change="syncBooking"></label><label>Start time<input v-model="form.start_time" type="time" required></label><label>End time<input v-model="form.end_time" type="time" :min="form.start_time" required></label></div><p class="muted">Start and end times are on the selected date, using Nepal time (NPT). Room, class and teacher conflicts are checked before saving.</p><button :disabled="!form.offering_id||!form.teacher_id||!canCheckTeachers||!!selectedTeacherBusy">{{busy?'Saving…':'Save special-room booking'}}</button></template></fieldset></form>
<section v-if="selectedRoom.kind==='regular' && assignment(selectedRoom.id)" class="booking-list"><h4>Usual classroom assignment</h4><p>{{className(classById(assignment(selectedRoom.id).class_id))}}</p><button class="secondary" :disabled="busy" @click="release(assignment(selectedRoom.id).class_id)">Release classroom</button></section>
<section v-if="selectedRoom.kind==='special'" class="booking-list"><h4>Bookings in this academic year</h4><p v-if="!roomBookings(selectedRoom.id).length" class="muted">No active bookings.</p><article v-for="b in roomBookings(selectedRoom.id)" :key="b.id"><strong>{{className(classById(b.class_id))}} · {{b.course_name}}</strong><p>{{b.repeats_weekly?days[b.day_of_week-1]+' weekly · ':''}}{{b.starts_on}}{{b.repeats_weekly?' to '+b.ends_on:''}}<br>{{b.start_time}}–{{b.end_time}} · {{b.teacher_name}}</p><button type="button" class="secondary" :disabled="busy" @click="cancelBooking(b.id)">Cancel booking</button></article></section></template></template></dialog>
</section>
</template>
<style scoped>
.room-board{color:#243e34}.board-heading,.board-toolbar,.dialog-heading{display:flex;align-items:center;justify-content:space-between;gap:18px}.board-heading h2{margin:4px 0;font-size:26px}.muted{font-size:13px;line-height:1.6;color:#6a7d73}.board-toolbar{margin:20px 0}.board-toolbar label{min-width:220px}.board-toolbar>p{font-size:12px}.key{display:inline-block;width:10px;height:10px;border-radius:3px;margin:0 4px 0 12px}.key.regular{background:#b8d7c6}.key.special{background:#b9b8dc}.board-workspace{display:grid;grid-template-columns:220px minmax(0,1fr);gap:18px;align-items:start}.class-library{background:white;border:1px solid #d9e4dc;border-radius:14px;padding:16px;position:sticky;top:12px}.class-library h3{margin:0 0 12px;font-size:17px}.class-library h3 span{font-size:12px;padding:3px 8px;border-radius:12px;background:#edf3ee}.class-list{max-height:460px;overflow:auto;display:grid;gap:9px}.class-card{display:block;text-align:left;padding:12px;background:#f2f7f3;border:1px solid #cdddce;color:#304d3e;border-radius:9px;touch-action:none;user-select:none;cursor:grab;width:100%}.class-card strong,.class-card small{display:block}.class-card small{font-size:11px;line-height:1.5;margin-top:5px;color:#6b7d70}.selected{outline:3px solid #b48135;outline-offset:-2px}.building-area{min-width:0}.board-instruction{font-size:13px;background:#eaf2ed;padding:12px;border-radius:9px;margin-top:0}.building-scroll{overflow:auto;border:1px solid #d9e4dc;background:#fff;border-radius:14px}.building{min-width:870px;padding:12px}.floor{display:grid;grid-template-columns:44px repeat(8,minmax(0,1fr));gap:8px;padding:12px 0;border-bottom:1px solid #e5ece7}.floor:last-child{border:0}.floor-label{display:flex;flex-direction:column;align-items:center;justify-content:center;position:sticky;left:0;background:white;z-index:1}.floor-label strong{font-size:28px}.floor-label small{font-size:8px;letter-spacing:1px;color:#85948b}.room{border:1px solid #c4dbcd;border-radius:10px;background:#f3f8f5;overflow:hidden;min-width:0;display:flex;flex-direction:column}.room.special{background:#f1f0fa;border-color:#cfcae6}.room.occupied{background:#e1efe6}.room-target{display:flex;flex-direction:column;align-items:start;gap:7px;background:transparent;color:#304e3d;text-align:left;padding:11px 8px;flex:1;width:100%}.special .room-target{color:#55507b}.room-number{font-size:20px}.room-name{font-size:11px;min-height:30px;line-height:1.4;overflow-wrap:anywhere}.room-status{font-size:9px;line-height:1.5;min-height:28px;color:#6b7d72}.special .room-status{color:#7c729c}.rename{font-size:9px;background:transparent;color:#718277;padding:6px;border-top:1px solid #d9e4dc;border-radius:0;width:100%}.drag-ghost{position:fixed;pointer-events:none;z-index:1000;background:#345c47;color:white;padding:12px;border-radius:8px;box-shadow:0 3px 12px #0003}label{display:block;font-size:13px;font-weight:600;margin:10px 0}input,select{box-sizing:border-box;width:100%;padding:10px;margin-top:5px;border:1px solid #c8d7cc;border-radius:7px;background:white;color:#2c4536;font:inherit;min-width:0}button{font:inherit;border:0;border-radius:8px;padding:10px 14px;background:#38624f;color:white;cursor:pointer;width:auto}button:disabled{opacity:.5;cursor:default}.secondary{background:#e8efea;color:#426551}button:focus-visible{outline:3px solid #b48135;outline-offset:2px}dialog{box-sizing:border-box;width:min(650px,calc(100vw - 24px));max-height:90vh;overflow:auto;border:1px solid #d4e0d7;border-radius:18px;padding:24px;color:#2b4435}dialog::backdrop{background:#16312380}.dialog-heading h3{margin:0;font-size:21px}.dialog-heading .eyebrow{font-size:10px;margin-top:0}.form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px}.check{display:flex;gap:9px;align-items:center}.check input{width:auto;margin:0}.chosen{background:#edf4ef;padding:12px;border-radius:8px;font-weight:600}fieldset{border:0;padding:0;min-width:0}.booking-list{border-top:1px solid #dce6df;padding-top:16px;margin-top:22px}.booking-list article{border-bottom:1px solid #e0e8e2;padding:12px 0;font-size:13px;line-height:1.6}.error,.success{padding:12px;border-radius:8px;font-size:13px}.error{background:#faeeeb;color:#a03d2e}.success{background:#e4f1e7;color:#38654a}@media(max-width:700px){.board-heading,.board-toolbar{align-items:stretch;flex-direction:column}.board-workspace{grid-template-columns:1fr}.class-library{position:static}.class-list{grid-template-columns:repeat(2,minmax(0,1fr));max-height:200px}.board-toolbar label{min-width:0}.board-heading h2{font-size:23px}dialog{padding:18px}}
.teacher-picker small{display:block;font-size:12px;color:#6a7d73;line-height:1.5}.teacher-picker .check{font-size:12px;margin:6px 0}
</style>
